/**
 * Arming the stop watch (`reminders/cloud-agent-stop-watch.ts`): one reminder
 * per launched agent, bound to the session whose turn launched it, so the
 * host wakes that conversation once the launched run stops.
 */
import { describeError } from "../../../internal/describe-error.js";
import extension from "../extension.js";
import stopWatch, { WATCH_WINDOW_HOURS, } from "../reminders/cloud-agent-stop-watch.js";
const WATCH_PURPOSE = "cloud_agent_stop_watch";
/** The shortest recurring interval every reminder control plane accepts. */
const POLL_INTERVAL = "1m";
/** Cloud Agents API run statuses of a launch whose run already stopped. */
const STOPPED_RUN_STATUSES = new Set([
    "finished",
    "error",
    "cancelled",
    "expired",
]);
/**
 * Watch a launched agent from this conversation unless it already does.
 * False when the mount opted out, the run already stopped, the host has no
 * reminders, the session has no continuation key, or arming failed; the
 * agent runs either way.
 */
export async function armWatch(ctx, launch) {
    const reminders = ctx.host.reminders;
    const continuationToken = ctx.session.continuationKey;
    if (!extension.config.watchStops ||
        STOPPED_RUN_STATUSES.has(launch.status) ||
        reminders === undefined ||
        continuationToken == null) {
        return false;
    }
    const { agentId } = launch;
    const { channelId } = ctx.session;
    try {
        const armed = await reminders.list({
            status: "armed",
            purpose: WATCH_PURPOSE,
            continuationToken,
        });
        if (armed.some((reminder) => reminder.channelId === channelId && watched(reminder) === agentId)) {
            return true;
        }
        const args = {
            agentId,
            deadline: new Date(Date.now() + WATCH_WINDOW_HOURS * 3_600_000).toISOString(),
        };
        await reminders.create({
            purpose: WATCH_PURPOSE,
            channelId,
            continuationToken,
            handler: stopWatch,
            args,
            every: POLL_INTERVAL,
            // A fire during a turn waits for it instead of skipping to the next poll.
            busyPolicy: "queueBehindTurn",
        });
        return true;
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not watch ${agentId}: ${describeError(error)}`);
        return false;
    }
}
/** End every watch on `agentId`, whose run was stopped on purpose. */
export async function disarmWatches(ctx, agentId) {
    const reminders = ctx.host.reminders;
    if (reminders === undefined) {
        return;
    }
    try {
        for (const reminder of await reminders.list({ status: "armed", purpose: WATCH_PURPOSE })) {
            if (watched(reminder) === agentId) {
                await reminders.cancel(reminder.id, "cloud_agent_cancelled");
            }
        }
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not stop watching ${agentId}: ${describeError(error)}`);
    }
}
function watched(reminder) {
    return reminder.args?.agentId;
}
